Let $p$ be an odd prime number, and let $\mathbb{F}_p$ denote the finite field with $p$ elements. Let $\chi: \mathbb{F}_p^\times \to \mathbb{C}^\times$ be a non-trivial multiplicative character of order $m \ge 3$, and extend $\chi$ to $\mathbb{F}_p$ by setting $\chi(0) = 0$. 

For each parameter $a \in \mathbb{F}_p^\times$, consider the matrix $T_\chi(a) \in \mathrm{M}_{p-1}(\mathbb{C})$ whose entries indexed by $u, v \in \mathbb{F}_p^\times$ are defined by:
$$[T_\chi(a)]_{u, v} = \chi\left(u - v\right) \exp\left( \frac{2\pi i}{p} a u v^{-1} \right), \qquad \forall u, v \in \mathbb{F}_p^\times.$$

Furthermore, let $G(a) = T_\chi(a) T_\chi(a)^*$ be the positive semi-definite Gram matrix associated with $T_\chi(a)$, where $T_\chi(a)^*$ denotes the Hermitian conjugate of $T_\chi(a)$.

\begin{enumerate}
    \item[\textbf{(a)}] \textbf{Spectral Trace Identities:} 
    For any integer $k \ge 1$, define the arithmetic moments:
    $$\mathcal{M}_k(p, \chi) = \sum_{a=1}^{p-1} \mathrm{Tr}\left( G(a)^k \right).$$
    Prove that for $k = 1$ and $k = 2$, $\mathcal{M}_k(p, \chi)$ is independent of the choice of the character $\chi$ of order $m$, and compute their exact closed-form values strictly in terms of $p$.

    \item[\textbf{(b)}] \textbf{Galois Invariance and Characteristic Polynomials:}
    Let $P_a(t) = \det(t I_{p-1} - G(a)) \in \mathbb{C}[t]$ be the characteristic polynomial of $G(a)$. 
    \begin{enumerate}
        \item[\textbf{(i)}] Prove that the coefficients of $P_a(t)$ lie in the cyclotomic field $K_m = \mathbb{Q}(\zeta_m)$, where $\zeta_m = e^{2\pi i / m}$.
        \item[\textbf{(ii)}] For $\sigma \in \mathrm{Gal}(K_m / \mathbb{Q})$ determined by $\sigma(\zeta_m) = \zeta_m^r$ with $\gcd(r, m) = 1$, establish whether $P_a^\sigma(t) = P_{a r'}(t)$ for some explicit arithmetic map $r' = \varphi(r, a) \in \mathbb{F}_p^\times$, or characterize the obstruction to such an orbit equivalence.
    \end{enumerate}

    \item[\textbf{(c)}] \textbf{Commutativity and Normality Criterion:}
    Determine, with complete proof, all pairs $(p, \chi)$ consisting of an odd prime $p$ and a character $\chi$ of order $m \ge 3$ such that $T_\chi(a)$ is a normal matrix (i.e., $T_\chi(a) T_\chi(a)^* = T_\chi(a)^* T_\chi(a)$) for \emph{all} $a \in \mathbb{F}_p^\times$.

    \item[\textbf{(d)}] \textbf{Extremal Spectral Gap:}
    Let $\lambda_{\max}(a)$ and $\lambda_{\min}(a)$ denote the largest and smallest eigenvalues of $G(a)$, respectively. Show that there exist absolute positive constants $C_1, C_2 > 0$, independent of $p$ and $m$, such that:
    $$C_1 p^2 \le \max_{a \in \mathbb{F}_p^\times} \lambda_{\max}(a) \le C_2 p^2 \log p.$$
\end{enumerate}

Let $n \ge 3$ be an integer. A simple, connected, undirected graph $G = (V, E)$ on $n$ vertices with adjacency matrix $A \in \operatorname{Mat}_{n \times n}(\{0, 1\})$ is called \emph{arithmetically harmonic} if it satisfies the following three conditions:

\begin{enumerate}
    \item[\textbf{(i)}] All eigenvalues $\lambda_1 > \lambda_2 > \dots > \lambda_n$ of $A$ are pairwise distinct, and the splitting field $K_G = \mathbb{Q}(\lambda_1, \dots, \lambda_n)$ has Galois group 
    $$\operatorname{Gal}(K_G / \mathbb{Q}) \cong S_n,$$
    the symmetric group on $n$ elements.

    \item[\textbf{(ii)}] The characteristic polynomial $P_G(x) = \det(x I_n - A) \in \mathbb{Z}[x]$ satisfies the polynomial recurrence congruence
    $$P_G(x+1) P_G(x-1) - P_G(x)^2 + 1 \equiv 0 \pmod{x^n - x}.$$

    \item[\textbf{(iii)}] The walk matrix $W(G, \mathbf{1}) = \begin{bmatrix} \mathbf{1} & A\mathbf{1} & A^2\mathbf{1} & \dots & A^{n-1}\mathbf{1} \end{bmatrix} \in \operatorname{Mat}_{n \times n}(\mathbb{Z})$ has determinant satisfying
    $$|\det W(G, \mathbf{1})| = \prod_{1 \le i < j \le n} |\lambda_i - \lambda_j|^{\frac{2}{n(n-1)}}.$$
\end{enumerate}

\noindent\textbf{Task:}
\begin{enumerate}
    \item[\textbf{(a)}] Prove that if $G$ is an arithmetically harmonic graph on $n$ vertices, then $n$ cannot be of the form $2^k$ for any integer $k \ge 2$.
    \item[\textbf{(b)}] Determine, with rigorous proof, the necessary and sufficient conditions on the integer $n \ge 3$ for the existence of an arithmetically harmonic graph $G$.
    \item[\textbf{(c)}] For all admissible values of $n$ found in part \textbf{(b)}, determine the exact multiset of eigenvalues $\operatorname{Spec}(A) = \{\lambda_1, \dots, \lambda_n\}$ in terms of algebraic invariants, and classify all graphs $G$ (up to graph isomorphism) that achieve arithmetic harmonicity.
\end{enumerate}
